import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { parseToolsetConfig, registerToolsets } from './lib/toolsets.js';
import { buildToolGroups } from './lib/tools.js';
export function registerTools(server, envToolsets) {
    const enabledToolsets = parseToolsetConfig(envToolsets ?? process.env.KANEO_TOOLSETS);
    const groups = buildToolGroups();
    registerToolsets(server, groups, enabledToolsets);
}
if (!process.env.VITEST) {
    const server = new McpServer({
        name: 'kaneo',
        version: '1.0.0',
    });
    registerTools(server);
    const transport = new StdioServerTransport();
    await server.connect(transport);
}
